import{_ as o,a0 as s,w as r,s as u,I as p,a1 as i,A as a,x as e,ao as l}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const f=JSON.parse('{"title":"圖解 Debian 10（Buster）安裝步驟 | LCTT x X-CMD","titleTemplate":false,"description":"圖解 Debian 10（Buster）安裝步驟 | LCTT (201907) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"圖解 Debian 10（Buster）安裝步驟 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"圖解 Debian 10（Buster）安裝步驟 | LCTT (201907) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201907/20190708 Debian 10 (Buster) Installation Steps with Screenshots","title":"圖解 Debian 10（Buster）安裝步驟","tag":"201907","desc":""},"relativePath":"201907/20190708 Debian 10 (Buster) Installation Steps with Screenshots.md","filePath":"[post].md"}'),d={name:"201907/20190708 Debian 10 (Buster) Installation Steps with Screenshots.md"};function w(b,t,h,m,c,D){const n=s("Link");return r(),u("div",null,[p("p",null,[i(n,{href:"collector:",title:"lujun9972"},{default:a(()=>[...t[0]||(t[0]=[e("#",-1)])]),_:1}),t[5]||(t[5]=e(": subject: (Debian 10 (Buster) Installation Steps with Screenshots) ",-1)),i(n,{href:"collector:",title:"lujun9972"},{default:a(()=>[...t[1]||(t[1]=[e("#",-1)])]),_:1}),t[6]||(t[6]=e(": via: (",-1)),i(n,{href:"https://www.linuxtechi.com/debian-10-buster-installation-guide/"},{default:a(()=>[...t[2]||(t[2]=[e("https://www.linuxtechi.com/debian-10-buster-installation-guide/",-1)])]),_:1}),t[7]||(t[7]=e(") ",-1)),i(n,{href:"collector:",title:"lujun9972"},{default:a(()=>[...t[3]||(t[3]=[e("#",-1)])]),_:1}),t[8]||(t[8]=e(": author: (Pradeep Kumar ",-1)),i(n,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:a(()=>[...t[4]||(t[4]=[e("https://www.linuxtechi.com/author/pradeep/",-1)])]),_:1}),t[9]||(t[9]=e(")",-1))]),t[26]||(t[26]=l('<h1 id="圖解-debian-10-buster-安裝步驟" tabindex="-1">圖解 Debian 10（Buster）安裝步驟 <a class="header-anchor" href="#圖解-debian-10-buster-安裝步驟" aria-label="Permalink to “圖解 Debian 10（Buster）安裝步驟”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/201907/11/000856swbwnfyknnbn3twk.jpg" alt=""></p><p>Debian 項目發佈了它的最新穩定版 Debian 10，其代號是 “Buster”，這個發佈版將獲得 5 年的支持。Debian 10 可用於 32 位和 64 位系統。這個發佈版帶來很多新的特色，列出下面一些特色：</p><ul><li>引入新的 Debian 10 的主題 “FuturePrototype”</li><li>新版本的電腦桌面環境 GNOME 3.30、Cinnamon 3.8、KDE Plasma 5.14、MATE 1.20、Xfce 4.12</li><li>長期支持版內核 4.19.0-4</li><li>新的 Python 3 (3.7.2)、Perl 5.28、PHP 7.3</li><li>iptables 替換為 nftables</li><li>更新 LibreOffice 6.1、GIMP 2.10.8</li><li>更新 OpenJDK 11、MariaDB 10.3 和 Apache 2.4.38</li><li>更新 Chromium 73.0、Firefox 60.7</li><li>改進 UEFI 支持</li></ul><p>在這篇文章中，我們將演示如何在你的筆記本電腦和台式電腦上安裝 Debian 10 “Buster” 工作站。</p><p>Debian 10 建議系統要求：</p><ul><li>2 GB 內存</li><li>2 GHz 雙核處理器</li><li>10 GB 可用硬盤空間</li><li>可啓動安裝介質（USB / DVD）</li><li>網絡連接（可選）</li></ul><p>讓我們跳轉到 Debian 10 的安裝步驟。</p><h3 id="步驟-1-下載-debian-10-iso-文件" tabindex="-1">步驟：1）下載 Debian 10 ISO 文件 <a class="header-anchor" href="#步驟-1-下載-debian-10-iso-文件" aria-label="Permalink to “步驟：1）下載 Debian 10 ISO 文件”">​</a></h3><p>從它的官方入口網站，下載 Debian 10 ISO 文件，</p>',10)),p("ul",null,[p("li",null,[i(n,{href:"https://www.debian.org/releases/buster/debian-installer/"},{default:a(()=>[...t[10]||(t[10]=[e("https://www.debian.org/releases/buster/debian-installer/",-1)])]),_:1})])]),t[27]||(t[27]=l('<p>ISO 文件下載完成後刻錄它到 USB 或 DVD，使其可用來啓動。</p><h3 id="步驟-2-使用安裝可啓動介質-usb-dvd-啓動你的電腦系統" tabindex="-1">步驟：2）使用安裝可啓動介質（USB / DVD）啓動你的電腦系統 <a class="header-anchor" href="#步驟-2-使用安裝可啓動介質-usb-dvd-啓動你的電腦系統" aria-label="Permalink to “步驟：2）使用安裝可啓動介質（USB / DVD）啓動你的電腦系統”">​</a></h3><p>重啓你將安裝 Debian 10 的電腦，轉到 BIOS 設置，並設置啓動介質為 USB 或 DVD。 用可啓動介質啓動電腦後，那麼我們將看到下面的屏幕。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Choose-Graphical-Install-Debian-10.jpg" alt=""></p><p>選擇第一個選項 “Graphical Install”。</p><h3 id="步驟-3-選擇你的首選語言、位置和鍵盤佈局" tabindex="-1">步驟：3）選擇你的首選語言、位置和鍵盤佈局 <a class="header-anchor" href="#步驟-3-選擇你的首選語言、位置和鍵盤佈局" aria-label="Permalink to “步驟：3）選擇你的首選語言、位置和鍵盤佈局”">​</a></h3><p>在這個步驟中，你將被要求選擇你的首選語言。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Choose-Language-Debian10-Installation.jpg" alt=""></p><p>點擊 “Continue”。</p><p>選擇你的首選位置，電腦系統將依照位置自動設置時區。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Select-Location-Debain10-Installation.jpg" alt=""></p><p>現在選擇適合於你安裝設備的鍵盤佈局。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Keyboard-Layout-Debian10-Installation.jpg" alt=""></p><p>點擊 “Continue” 以繼續。</p><h3 id="步驟-4-為-debian-10-系統設置主機名稱和域名" tabindex="-1">步驟：4）為 Debian 10 系統設置主機名稱和域名 <a class="header-anchor" href="#步驟-4-為-debian-10-系統設置主機名稱和域名" aria-label="Permalink to “步驟：4）為 Debian 10 系統設置主機名稱和域名”">​</a></h3><p>設置適合於你的環境的主機名，然後在 “Continue” 上單擊，就我而言, 我指定主機名為 “debian10-buster”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Hostname-During-Debian10-Installation.jpg" alt=""></p><p>指定適合於環境的域名，並安裝，然後在 “Continue” 上單擊。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Domain-Name-During-Debian10-Installation.jpg" alt=""></p><h3 id="步驟-5-指定-root-用户的密碼" tabindex="-1">步驟：5）指定 root 用户的密碼 <a class="header-anchor" href="#步驟-5-指定-root-用户的密碼" aria-label="Permalink to “步驟：5）指定 root 用户的密碼”">​</a></h3><p>在下面的屏幕中指定 root 密碼，然後在 “Continue” 上單擊。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Root-Password-Debian10-Installation.jpg" alt=""></p><h3 id="步驟-6-創建本地用户和它的密碼" tabindex="-1">步驟：6）創建本地用户和它的密碼 <a class="header-anchor" href="#步驟-6-創建本地用户和它的密碼" aria-label="Permalink to “步驟：6）創建本地用户和它的密碼”">​</a></h3><p>在這個步驟中，你將被提示指定本地用户具體信息，如完整的姓名、用户名和密碼，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Local-User-FullName-Debian10.jpg" alt=""></p><p>在 “Continue” 上單擊。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/UserName-LocalUser-Debian10-Installation.jpg" alt=""></p><p>在 “Continue” 上單擊，並在接下來的窗口中指定密碼。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Password-Localuser-Debian10.jpg" alt=""></p><h3 id="步驟-7-為-debian-10-選擇硬盤分區方案" tabindex="-1">步驟：7）為 Debian 10 選擇硬盤分區方案 <a class="header-anchor" href="#步驟-7-為-debian-10-選擇硬盤分區方案" aria-label="Permalink to “步驟：7）為 Debian 10 選擇硬盤分區方案”">​</a></h3><p>在這個步驟中，為 Debian 10 選擇硬盤分區方案，就我而言，我有 40 GB 硬盤可用於操作系統安裝。分區方案有兩種類型：</p><ul><li>嚮導分區（安裝器將自動創建需要的分區）</li><li>手動分區（正如名字所示，使用這種方式，我們可以手動創建分區方案）</li></ul><p>在這篇教程中，我們將在我 42 GB 硬盤上使用帶有 LVM 的嚮導分區。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Choose-Guided-Partitioning-Scheme-Debain10-Installation.jpg" alt=""></p><p>在 “Continue” 上單擊來繼續，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Hard-Disk-Debian10-Installation.jpg" alt=""></p><p>正如我們所視，我大約有 42 GB 硬盤空間，選擇 “Continue”。</p><p>在接下來的屏幕中，你將被要求選擇分區，如果是 Linux 新用户，那麼選擇第一個選項。假使你想要一個獨立的 home 分區，那麼選擇第二種方案，否則選擇第三種方案，它們將為 <code>/home</code>、<code>/var</code> 和 <code>/tmp</code> 創建獨立的分區。</p><p>就我而言，我將通過選擇第三種選項來為 <code>/home</code>、<code>/var</code> 和 <code>/tmp</code> 創建獨立的分區。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Guided-Separate-Partitions-Debian10-Installation.jpg" alt=""></p><p>在接下來的屏幕中，選擇 “yes” 來將更改寫到磁盤中，配置 LVM ，然後在 “Continue” 上單擊。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Write-Changes-Disk-Debian10-Installation.jpg" alt=""></p><p>在接下來的屏幕中，將顯示分區表，驗證分區大小、文件系統類型和掛載點。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Debian10-Partition-Table.jpg" alt=""></p><p>在 “Continue” 上單擊來繼續，</p><p>在接下來的屏幕中，選擇 “yes” 來寫更改到磁盤中，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Choose-Yes-Write-Changes-Disk-Debian10-Installation.jpg" alt=""></p><p>在 “Continue” 上單擊來繼續安裝，</p><h3 id="步驟-7-debian-10-安裝開始" tabindex="-1">步驟：7）Debian 10 安裝開始 <a class="header-anchor" href="#步驟-7-debian-10-安裝開始" aria-label="Permalink to “步驟：7）Debian 10 安裝開始”">​</a></h3><p>在這一步驟中，Debian 10 的安裝已經開始，並正在進行中，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Debian10-Installation-Progress.jpg" alt=""></p><p>在安裝期間，安裝器將提示你掃描 CD/DVD 以配置軟件包管理器，選擇 “No” ，然後在 “Continue” 上單擊。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Scan-DVD-Debian10-Installation.jpg" alt=""></p><p>在接下來的屏幕中，如果你想配置基於網絡的軟件包管理器選擇 “yes” ，但是為了使這個方式工作，要確保你的系統連接到了網絡，否則選擇 “No”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Network-Mirror-Debian10-Package-Manager.jpg" alt=""></p><p>在 “Continue” 上單擊來配置基於你本地的軟件包管理器，在接下來的幾個屏幕中，你將被提示選擇本地和 Debian 軟件包存儲庫 URL ，然後你將獲得下面的屏幕。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Apt-Config-Debian10-Installation.jpg" alt=""></p><p>選擇 “No” 來跳過軟件包審查步驟，然後在 “Continue” 上單擊。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Pkg-Survey-Debian10-Installation.jpg" alt=""></p><p>在接下來的窗口中，你將被提示選擇電腦桌面環境和其它軟件包，就我而言，我選擇 “Gnome Desktop” ，“SSH Server” 和 “Standard System utilities”。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Software-Selection-Debian10-Installation.jpg" alt=""></p><p>在 “Continue” 上單擊來繼續安裝，</p><p>選擇選項 “yes” 來安裝 Grub 引導加載程序。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Install-Grub-Bootloader-Debian10-Installation.jpg" alt=""></p><p>在 “Continue” 上單擊來繼續，然後在接下來的窗口中選擇將安裝引導加載程序的磁盤（<code>/dev/sda</code>）。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Install-grub-on-dev-sda-debian10.jpg" alt=""></p><p>在 “Continue” 上單擊來繼續安裝，一旦安裝完成，安裝器將提示我們來重啓系統，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Installation-Completed-Debain10.jpg" alt=""></p><p>在 “Continue” 上單擊來重啓你的系統，不要忘記在 BIOS 設置中更改啓動介質，以便系統從我們已經安裝 Debian 10 操作系統的硬盤啓動。</p><h3 id="步驟-8-啓動你新安裝的-debian-10-系統" tabindex="-1">步驟：8）啓動你新安裝的 Debian 10 系統 <a class="header-anchor" href="#步驟-8-啓動你新安裝的-debian-10-系統" aria-label="Permalink to “步驟：8）啓動你新安裝的 Debian 10 系統”">​</a></h3><p>在成功安裝後，一旦我們重啓系統，我們將獲取下面的引導加載程序屏幕。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Bootloader-Screen-Debian10.jpg" alt=""></p><p>選擇第一個選項 “Debian GNU/Linux” 並敲擊回車鍵。</p><p>一旦系統啓動，使用我在安裝期間創建的本地用户和它的密碼。</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Local-User-Debian10-Login.jpg" alt=""></p><p>在成功登錄後，將看到如下電腦桌面屏幕，</p><p><img src="https://www.linuxtechi.com/wp-content/uploads/2019/07/Desktop-Screen-Debian10-Buster.jpg" alt=""></p><p>這證實 Debian 10 已經成功安裝，這就是本文的全部，探索這個令人激動的 Linux 發行版吧，玩得開心 😊</p><hr>',79)),p("p",null,[t[12]||(t[12]=e("via: ",-1)),i(n,{href:"https://www.linuxtechi.com/debian-10-buster-installation-guide/"},{default:a(()=>[...t[11]||(t[11]=[e("https://www.linuxtechi.com/debian-10-buster-installation-guide/",-1)])]),_:1})]),p("p",null,[t[17]||(t[17]=e("作者：",-1)),i(n,{href:"https://www.linuxtechi.com/author/pradeep/"},{default:a(()=>[...t[13]||(t[13]=[e("Pradeep Kumar",-1)])]),_:1}),t[18]||(t[18]=e(" 選題：",-1)),i(n,{href:"https://github.com/lujun9972"},{default:a(()=>[...t[14]||(t[14]=[e("lujun9972",-1)])]),_:1}),t[19]||(t[19]=e(" 譯者：",-1)),i(n,{href:"https://github.com/robsean"},{default:a(()=>[...t[15]||(t[15]=[e("robsean",-1)])]),_:1}),t[20]||(t[20]=e(" 校對：",-1)),i(n,{href:"https://github.com/wxy"},{default:a(()=>[...t[16]||(t[16]=[e("wxy",-1)])]),_:1})]),p("p",null,[t[23]||(t[23]=e("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:a(()=>[...t[21]||(t[21]=[e("LCTT",-1)])]),_:1}),t[24]||(t[24]=e(" 原創編譯，",-1)),i(n,{href:"https://linux.cn/"},{default:a(()=>[...t[22]||(t[22]=[e("Linux中國",-1)])]),_:1}),t[25]||(t[25]=e(" 榮譽推出",-1))])])}const C=o(d,[["render",w]]);export{f as __pageData,C as default};
